    const originPath = (value) => {
      const u = new URL(value);
      return u.origin + u.pathname;
    };
    if (
      !url ||
      originPath(url) !== originPath(activePage.url()) ||
      context.pages().length !== 1
    )
      throw new Error("MCP and native computer page binding not established");
    knownPages = [activePage];
    selectedPage = activePage;
    protocol.exposedMcpTools = selected
      .filter((tool) => selectedMcpNames.has(tool.name))
      .map((tool) => tool.name);
